% Backward: gradients w.r.t. inputs (L4E, L4I, L6); Contrast treated constant
sig_out = 1 ./ (1 + exp(-Z3));      % dy/dZ3 for softplus
dh2 = 1 - H2.^2;
dh1 = 1 - H1.^2;

dy_dh2 = sig_out .* W3;
dy_dZ2 = dy_dh2 .* dh2;
dy_dh1 = dy_dZ2 * W2;
dy_dZ1 = dy_dh1 .* dh1;
dy_dXn = dy_dZ1 * W1;
dy_dX  = dy_dXn ./ sd;             % de-normalize all inputs

% Outputs (same names as function signature)
dL4E = reshape(dy_dX(:,1), origSize);
dL4I = reshape(dy_dX(:,2), origSize);
dL6  = reshape(dy_dX(:,3), origSize);
y    = reshape(y_raw, origSize);
end
